INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`SoundPlayType`,`BroadcastTextId`,`TextRange`,`comment`) VALUES
(247126,0,0,'When he arrives we will be ready.',14,0,100.0,0,0,0,0,0,0,'Atrexis the Grave Knight - out of combat 1 (official 70338 A 114987)'),
(247126,1,0,'Bring another; we are running out of time.',14,0,100.0,0,0,0,0,0,0,'Atrexis the Grave Knight - out of combat 2 (A 119396)'),
(247126,2,0,'Get them out of the halls; we don''t need idle snooping.',14,0,100.0,0,0,0,0,0,0,'Atrexis the Grave Knight - out of combat 3 (A 125948)'),
(247126,3,0,'Cart those bodies from the hall. He does not want to be kept waiting.',14,0,100.0,0,0,0,0,0,0,'Atrexis the Grave Knight - out of combat 4 (A 133037)'),
(247126,4,0,'Excellent. Bring more.',14,0,100.0,0,0,0,0,0,0,'Atrexis the Grave Knight - out of combat 5 (A 140885)'),
(247126,5,0,'A hidden blessing.',14,0,100.0,0,0,0,0,0,0,'Atrexis the Grave Knight - aggro (A 143256 / 173865)'),
(247126,6,0,'Perhaps my work was enough...',14,0,100.0,0,0,0,0,0,0,'Atrexis the Grave Knight - death (A 179708)');
